#!/usr/bin/env python3
"""Create auditable empty proposal shells when current evidence fails eligibility gates."""
from pathlib import Path
import csv,json,hashlib
from datetime import datetime,timezone
R=Path(__file__).resolve().parents[1]
packages={
'restored_temperature':('P1','RESTORED','outTemp','8,965 shared source-copy NULL candidates, 2009–2020. Exact matching copies are treated as one copied observation, not independent measurements.','Missing verified historical archive role/lineage, driver epoch, target unit transform, per-row original measurement identity and context gate. 2013 July negative anomalies, suspected long zero runs, long outages, freeze/inversion, Q1 2018 and all 2021 excluded or review-only.','reports/2026-11-12-outtemp-source-copy-screening.md; reports/2026-11-12-source-null-candidate-history-reconciliation.md; reports/2026-11-12-outtemp-2013-july-source-anomaly.md','ER-01; ER-02; ER-11; ER-12; ER-14; ER-25'),
'restored_humidity':('P2','RESTORED','outHumidity','30,391 shared source RH pairs; six known conflicts retained for review.','Historical original sensor/config/calibration/lineage and per-target change-history review not established. Shared-copy concordance alone is insufficient. Conflicts, applied/changed targets, Q1 2018 and 2021 excluded.','reports/2026-11-12-rh-source-conflicts.md; reports/2026-11-12-source-null-candidate-history-reconciliation.md','ER-11; ER-25'),
'estimated_short_temperature_gaps':('P3','ESTIMATED','outTemp','Previously completed 2019–2020 seasonal masked-block scores; synthetic complete-data masks only.','No eligible real target set yet: gap classification/expected cadence and MCAR/MNAR comparability not proven; actual weather regime, anomaly flags and target history must be checked. No ≥24h interpolation. Freeze/inversion and extremes excluded pending expert criteria.','reports/2026-11-13-temperature-interpolation-seasonal-blocks.md; reports/2026-11-13-temperature-interpolation-block-extrema.md; reports/2026-11-13-temperature-short-gap-interpolation-holdout-2019-07.md','ER-01; ER-02; ER-07; ER-07 follow-up'),
'estimated_humidity_2022':('P4','ESTIMATED','outHumidity','2022-01-30 through 2022-02-28: 8,634 archive rows; 8,632 exact LuhaMet RH timestamps, in a 2022 archive with 104,142 rows and 41,727 current RH NULL.','No independent validation on comparable trusted local winter measurements; LuhaMet station coordinates/license/sensor continuity unavailable; March same-period complete-case is not an independent holdout and has MAE 2.82 pp/RMSE 4.22 pp. Mraz, inversion, fog and sensor epoch gates unmet.','reports/2026-11-13-rh-luhamet-outage-2022-source-coverage.md; reports/2026-11-13-rh-vapor-pressure-transfer-holdout.md','ER-01; ER-02; ER-07; ER-10; ER-31'),
'restored_secondary_sensors':('P5','RESTORED','multiple secondary variables','42 secondary fields exact across production/reconstruction for shared rows 2024–2026 (304,758 rows).','Recent cross-archive concordance does not prove original sensor identity, lineage into target archive, expected NULL state or restoration eligibility. No candidate set has all per-row provenance/QC gates. 2021 excluded.','reports/2026-11-13-secondary-exact-cross-archive-2024-2026.md; reports/2026-11-13-monthly-archive-field-availability-2009-2026.md','ER-06; ER-18; ER-19; ER-20; ER-21; ER-25')}
for name,(priority,category,variable,scope,blocker,evidence,review) in packages.items():
 d=R/'proposals'/name;d.mkdir(parents=True,exist_ok=True)
 candidates=[]
 exclusions=[]
 if name=='restored_temperature':
  with (R/'reports/2026-11-12-outtemp-source-copy-annual.csv').open(newline='',encoding='utf8') as f:
   for row in csv.DictReader(f):
    exclusions.append({'scope':f"UTC {row['utc_year']}; old_weewx + weewx_WH1080 exact timestamp; usUnits=17/interval=5; target outTemp NULL/no history",'candidate_count':int(row['paired_targets']),'disposition':'REVIEW_REQUIRED_NO_RESTORED_PROVENANCE','reason':'Both source copies agree, but their historical role/lineage and conversion into target usUnits=16 are undocumented; agreement is integrity evidence, not independent truth.'})
  exclusions.append({'scope':'2013-07-01 02:00–06:45 UTC; 18 negative source-copy observations','candidate_count':18,'disposition':'EXCLUDE_PENDING_ER12','reason':'Known negative summer anomaly cohort: 17 values −0.6 °C and one −9.6 °C; keep out of restoration proposals pending sensor/source review. These 18 are a subset of the 2013 cohort, not additional candidates.'})
  with (R/'reports/2026-11-12-long-gap-outtemp-source-availability.csv').open(newline='',encoding='utf8') as f:
   for row in csv.DictReader(f):
    exclusions.append({'scope':f"Source-only diagnostic window {row['period_utc']}; {row['shared_timestamps']} shared source timestamps; {row['old_outTemp_nonnull']} old / {row['weewx_WH1080_outTemp_nonnull']} WH1080 non-NULL",'candidate_count':int(row['shared_timestamps']),'disposition':'OUTSIDE_P1_EXISTING_ROW_NULL_INVENTORY; REVIEW_REQUIRED','reason':f"Not part of the 8,965 existing-row NULL candidates: exact reconstruction targets are absent in these long-gap windows. WH1080 has {row['WH1080_zero']} zero values and {row['WH1080_negative']} negative values; do not insert or interpolate without timestamp/cadence and sensor-provenance evidence (ER-01/02/11)."})
 elif name=='restored_humidity':
  exclusions.append({'scope':'30,385 common exact-time RH source pairs with exact value agreement','candidate_count':30385,'disposition':'REVIEW_REQUIRED_NO_RESTORED_PROVENANCE','reason':'Source sensor role, calibration epoch, archive lineage and target-unit semantics are not documented; matching copies alone do not establish eligibility.'})
  with (R/'reports/2026-11-12-rh-source-conflict-problem-cases.csv').open(newline='',encoding='utf8') as f:
   for row in csv.DictReader(f):
    exclusions.append({'scope':f"{row['target_utc']}; old_weewx vs weewx_WH1080",'candidate_count':1,'disposition':'REVIEW_REQUIRED_ER11_CONFLICT','reason':f"RH source conflict {row['old_outHumidity']} vs {row['wh_outHumidity']} percentage points; target remains NULL and neither copy is preferred."})
 elif name=='estimated_humidity_2022':
  exclusions.extend([
   {'scope':'2022-01-30 through 2022-02-28 archive rows','candidate_count':8634,'disposition':'REVIEW_REQUIRED_ER31','reason':'8,632 exact LuhaMet RH values available, but no independent comparable local winter holdout; coordinate/license/sensor continuity and frost/fog/inversion validation unmet.'},
   {'scope':'same long outage: no exact LuhaMet RH observation','candidate_count':2,'disposition':'NO_REFERENCE_VALUE','reason':'No exact-time reference value in source availability snapshot.'},
   {'scope':'March 2022 same-period complete-case comparison','candidate_count':1692,'disposition':'VALIDATION_ONLY_NOT_INDEPENDENT_HOLDOUT','reason':'Observed target/reference MAE 2.82 pp and RMSE 4.22 pp; not a pre-registered independent winter local validation.'}])
 elif name=='estimated_short_temperature_gaps':
  exclusions.append({'scope':'2019–2020 synthetic masked-block validation','candidate_count':19714,'disposition':'VALIDATION_EVIDENCE_ONLY_NOT_REAL_TARGETS','reason':'All masked targets were known complete observations; this does not establish that actual missingness is comparable or identify candidate timestamps.'})
 elif name=='restored_secondary_sensors':
  with (R/'reports/2026-11-13-secondary-exact-cross-archive-2024-2026.csv').open(newline='',encoding='utf8') as f:
   for row in csv.DictReader(f):
    exclusions.append({'scope':f"{row['year']} {row['variable']} production/reconstruction exact-time overlap",'candidate_count':int(row['both_nonnull']),'disposition':'CONCORDANCE_ONLY_NOT_RESTORATION_CANDIDATES','reason':'Both archives contain matching values at these timestamps; this is not a source-null restoration target set and does not prove independent physical measurements.'})
 if not exclusions: exclusions=[{'scope':scope,'candidate_count':0,'disposition':'NO_ROW_LEVEL_TARGET_SET','reason':blocker}]
 (d/'corrections.json').write_text(json.dumps(candidates,indent=2)+'\n',encoding='utf8')
 with (d/'corrections.csv').open('w',newline='',encoding='utf8') as f:
  w=csv.writer(f);w.writerow(['operation','timestamp','variable','new_value','expected_old_value','source_database','source_time','source_value','category','uncertainty','reason','dependencies']);
 with (d/'excluded_cases.csv').open('w',newline='',encoding='utf8') as f:
  w=csv.DictWriter(f,fieldnames=['scope','candidate_count','disposition','reason']);w.writeheader();w.writerows(exclusions)
 batch={'contract':'Weather MCP reconstruction_apply_corrections; 1–50 corrections; stable batch_id; dry_run=True default','batches':[],'status':'NO_CANDIDATES; no MCP call made','safety':'No staging or database write; package proposal only'}
 (d/'weather_mcp_batches.json').write_text(json.dumps(batch,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
 (d/'simulation.json').write_text(json.dumps({'status':'NOT_RUN_NO_VALIDATED_CANDIDATES','offline_only':True,'database_access':False,'candidate_count':0,'reason':'Current evidence does not satisfy RESTORED/ESTIMATED eligibility gates; simulator requires a validated candidate and exact source/target snapshot.'},ensure_ascii=False,indent=2)+'\n',encoding='utf8')
 (d/'source_validation_metadata.json').write_text(json.dumps({'source_evidence':evidence.split('; '),'expected_original_state':'Target expected NULL/no prior target-variable correction history where applicable; must be verified per row before candidate creation.','source_role':scope,'unit_and_timestamp':'For P1 exact source timestamps and raw usUnits=17/interval=5 are verified on the shared candidates; target archive uses usUnits=16 and historical transformation is undocumented. For other packages use the cited report-specific scope; no candidate-level semantic gate has passed.','confidence':'No candidate-level confidence assigned; package remains review/blocked.','dependencies':review.split('; ')},ensure_ascii=False,indent=2)+'\n',encoding='utf8')
 manifest_obj={'package':name,'priority':priority,'classification':category,'variable':variable,'candidate_count':0,'scope_records':scope,'decision':'NO SAFE CANDIDATES EMITTED','exclusion_scopes_non_additive':True,'exclusion_count_note':'Counts refer to overlapping and semantically distinct evidence scopes; do not sum across package rows. P1 annual groups total 8,965; July anomaly and long-gap rows overlap/subset or are explicitly outside that target inventory. P5 are year-variable concordance observations, not NULL target candidates.','blocker':blocker,'evidence':evidence.split('; '),'expert_review_groups':review.split('; '),'exclusions_file':'excluded_cases.csv','mcp_batches_file':'weather_mcp_batches.json','simulation_file':'simulation.json','safety':{'database':'READ_ONLY','staging':'prohibited','apply':'prohibited','q1_2018':'excluded','2021':'diagnostic_only_excluded'}}
 for artifact in sorted(d.iterdir()):
  if artifact.is_file() and artifact.name!='manifest.json': manifest_obj.setdefault('artifacts',{})[artifact.name]={'bytes':artifact.stat().st_size,'sha256':hashlib.sha256(artifact.read_bytes()).hexdigest()}
 (d/'manifest.json').write_text(json.dumps(manifest_obj,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
 (d/'README.md').write_text(f'''# {priority} — {name}\n\nStav: **žádné způsobilé korekční návrhy** (0 candidates).\n\n{scope}\n\nBlokátor: {blocker}\n\nKlasifikace zamýšlených kandidátů: `{category}`. Toto není schválení zápisu. JSON/CSV jsou prázdné datové dávky; důvody vyloučení jsou uvedeny v `excluded_cases.csv`. Validace struktury: `../../scripts/validate_priority_proposal_shells.py`. Offline simulace nebyla spuštěna na prázdném balíčku a MCP dávka nebyla odeslána. Podklady: {evidence}. Expert skupiny: {review}.\n\nQ1 2018 je mimo návrhy; rok 2021 zůstává pouze diagnostický.\n''',encoding='utf8')
 manifest_obj['artifacts']={artifact.name:{'bytes':artifact.stat().st_size,'sha256':hashlib.sha256(artifact.read_bytes()).hexdigest()} for artifact in sorted(d.iterdir()) if artifact.is_file() and artifact.name!='manifest.json'}
 (d/'manifest.json').write_text(json.dumps(manifest_obj,ensure_ascii=False,indent=2)+'\n',encoding='utf8')

# Extend register with ER-31 (previously documented, omitted in CSV) and classify every row.
reg=R/'reports/2026-11-13-expert-review-register.csv'
with reg.open(newline='',encoding='utf8') as f: rows=list(csv.DictReader(f)); fields=list(rows[0])
if not any(x['issue_id']=='ER-31' for x in rows):
 rows.append({'issue_id':'ER-31','title':'Dlouhý výpadek outHumidity v roce 2022 a přenos LuhaMet → Loučka','quality_status':'REVIEW_REQUIRED','review_tags':'LONG_OUTAGE;RH;WINTER;FOG;INVERSION;MODEL_UNCERTAINTY','protected_2021':'false','q1_2018_interim':'false','register_scope':'issue_group_only_not_row_level_quality_classification','evidence_source':'EXPERT_REVIEW_REQUIRED.md#er-31'})
fields+=['impact_class','affected_scope','affected_proposals','evidence_required']
block_specific={'ER-01':('BLOCKS_SPECIFIC_CORRECTIONS','period-specific gaps with unproven cadence','P3;P4','Documented station cadence/epoch and gap classification'), 'ER-02':('BLOCKS_SPECIFIC_CORRECTIONS','long outages, freeze/inversion periods','P1 long runs; P3 flagged regimes; P4 winter','Independent local truth and validated uncertainty by regime'), 'ER-07':('BLOCKS_SPECIFIC_CORRECTIONS','temperature reference transfer','P3 model-derived; P4 if LuhaMet transfer used','Independent chronological/regime validation'), 'ER-07 follow-up':('BLOCKS_SPECIFIC_CORRECTIONS','masked interpolation extrema','P3 extreme-sensitive proposals','Validation of extrema attenuation on actual target regimes'), 'ER-11':('BLOCKS_SPECIFIC_CORRECTIONS','conflicting RH archive copies and suspicious temp groups','P1 affected groups; P2 six conflicts','Original-source lineage and conflict resolution'), 'ER-12':('BLOCKS_SPECIFIC_CORRECTIONS','July 2013 negative outTemp candidates','P1 affected 2013 July rows','Sensor fault vs true measurement evidence'), 'ER-14':('BLOCKS_SPECIFIC_CORRECTIONS','2013 joint T/RH plateau runs','P1 affected plateau rows','Original packet/config evidence'), 'ER-23':('BLOCKS_SPECIFIC_CORRECTIONS','Q1 2018 reconstruction scope','No new proposals; protected interim','Authoritative approval manifest and target scope'), 'ER-24':('BLOCKS_SPECIFIC_CORRECTIONS','2021 rain history targets','None; protected diagnostic only','Authoritative artifact/apply provenance; no correction in this goal'), 'ER-31':('BLOCKS_SPECIFIC_CORRECTIONS','2022-01-30 through 2022-02-28 outHumidity','P4','Independent comparable winter local validation; station history/coords; frost/fog/inversion validation'), 'ER-33':('BLOCKS_SPECIFIC_CORRECTIONS','5,416 exact-zero outTemp source timestamps in short gaps (2014–2018 plus one 2020 target)','RESTORED vs ESTIMATED only for affected timestamps','Authenticated archive/driver lineage, zero sentinel semantics, sensor history, source packets and per-target neighbor/reference validation')}
blocks_pub={'ER-05','ER-20','ER-21','ER-23','ER-24','ER-29','ER-30'}
for x in rows:
 iid=x['issue_id']
 if iid in block_specific: c,scope,props,proof=block_specific[iid]
 elif iid in blocks_pub: c,scope,props,proof=('BLOCKS_FINAL_PUBLICATION','specified issue group; no blanket hold on unrelated corrections','Final integrated package only; unrelated validated proposals remain eligible','Issue-specific provenance/QC decision and explicit limits')
 else: c,scope,props,proof=('NON_BLOCKING_FOLLOWUP',x['title'],'No currently identified priority package dependency','Evidence listed in EXPERT_REVIEW_REQUIRED.md; retain open until resolved')
 x.update(impact_class=c,affected_scope=scope,affected_proposals=props,evidence_required=proof)
with reg.open('w',newline='',encoding='utf8') as f:
 w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rows)
print('created packages',len(packages),'expert review groups',len(rows))
